/* a kid with a sad mouth (covers kid()'s smile) */
const sad7=(x,y,shirt,hair,s=1)=>kid(x,y,shirt,hair,s)+`<path d="M${x-6*s} ${y+11*s} Q${x} ${y+15*s} ${x+6*s} ${y+11*s}" stroke="#f1c7a3" stroke-width="${4*s}" fill="none"/><path d="M${x-6*s} ${y+14*s} Q${x} ${y+9*s} ${x+6*s} ${y+14*s}" stroke="#1d2433" stroke-width="${2*s}" fill="none" stroke-linecap="round"/>`;

/* ---------------- unit 3: Finalen (ordklasser: substantiv, verb, adjektiv) ---------------- */
W("laktare",{sv:"läktare (en)",m:rx("läktar(e|en|na)"),d:t3("Platsen där publiken sitter och tittar på en match.","The stands where the audience sits and watches a match.","المكان الذي يجلس فيه الجمهور لمشاهدة المباراة."),ex:"Läktaren var full av folk.",tr:{en:"stand, stands",ar:"مدرّجات"},syn:["tribun"],wrong:["omklädningsrum","målvakt"],gap:["Föräldrarna satt på","läktaren","och tittade på matchen."],gapForm:"läktaren",form:"en läktare – läktare"});
W("domare",{sv:"domare (en)",m:rx("domar(e|en|na)"),d:t3("Den som leder matchen och ser till att alla följer reglerna.","The person who leads the match and makes sure everyone follows the rules.","الشخص الذي يدير المباراة ويتأكد من أن الجميع يتبعون القواعد."),ex:"Domaren blåste i visslan.",tr:{en:"referee",ar:"حَكَم"},syn:["skiljedomare"],wrong:["tränare","publik"],gap:["När matchen var slut, blåste","domaren","i visslan."],gapForm:"domaren",form:"en domare – domare"});
W("straff",{sv:"straffspark (en)",m:rx("straff(spark)?(en|ar|arna)?"),d:t3("En spark mot mål från en punkt, med bara målvakten emot. Kallas också straff.","A kick at goal from a spot, with only the goalkeeper against you. Also called straff.","ركلة نحو المرمى من نقطة محددة، ولا يقف أمامك إلا حارس المرمى. تُسمّى أيضًا straff."),ex:"Amir satte sin straff.",tr:{en:"penalty kick",ar:"ركلة جزاء"},syn:["straff"],wrong:["hörna","inkast"],gap:["Finalen avgjordes med","straffsparkar","efter 1–1."],gapForm:"straffsparkar",form:"en straffspark – straffsparkar"});
W("waga",{sv:"våga",m:rx("våga(r|de|t)?"),d:t3("Göra något fast man är rädd.","Do something even though you are scared.","أن تفعل شيئًا رغم أنك خائف."),ex:"Han vågade skjuta den sista straffen.",tr:{en:"dare",ar:"يجرؤ"},syn:["ha mod","töras"],wrong:["sova","glömma"],gap:["Han var rädd, men han bestämde sig för att","våga","skjuta."],gapForm:"våga",form:"våga – vågade – har vågat"});
W("besviken",{sv:"besviken",m:rx("besvik(en|et|na)"),d:t3("Ledsen för att något inte blev som man hoppades.","Sad because something did not turn out as you hoped.","حزين لأن شيئًا لم يحدث كما كنت تأمل."),ex:"Sara var besviken när hon missade.",tr:{en:"disappointed",ar:"خائب الأمل"},syn:["nedstämd","ledsen"],wrong:["hungrig","pigg"],gap:["Hon blev","besviken","när målvakten räddade hennes straff."],gapForm:"besviken",form:"besviken – besviket – besvikna"});
W("stolt",{sv:"stolt",m:rx("stolt(a)?"),d:t3("Glad och nöjd över något som man själv eller någon annan har gjort.","Happy and pleased about something you or someone else has done.","سعيد وراضٍ عن شيء فعلته أنت أو فعله شخص آخر."),ex:"Tränaren var stolt över laget.",tr:{en:"proud",ar:"فخور"},syn:["nöjd"],opp:["skamsen"],wrong:["rädd","trött"],gap:["Tränaren var så","stolt","över laget."],gapForm:"stolt",form:"stolt – stolt – stolta"});
W("tvivla",{sv:"tvivla",m:rx("tvivla(r|de|t)?"),d:t3("Inte vara säker på något, till exempel på att man klarar det.","Not be sure about something, for example that you can do it.","ألّا تكون متأكدًا من شيء، مثلًا من أنك تستطيع فعله."),ex:"Han började tvivla på sig själv.",tr:{en:"doubt",ar:"يشكّ"},syn:["vara osäker"],opp:["vara säker"],wrong:["springa","skratta"],gap:["Amir började","tvivla","på att han skulle klara det."],gapForm:"tvivla",form:"tvivla – tvivlade – har tvivlat"});
W("applodera",{sv:"applådera",m:rx("applådera(r|de|t)?"),d:t3("Klappa händerna för att visa att man tycker om något.","Clap your hands to show that you like something.","أن تصفّق بيديك لتُظهر أنك أعجبت بشيء."),ex:"Publiken applåderade länge.",tr:{en:"applaud, clap",ar:"يصفّق"},syn:["klappa händerna"],opp:["bua"],wrong:["viska","gråta"],gap:["Efter målet reste sig alla och började","applådera","."],gapForm:"applådera",form:"applådera – applåderade – har applåderat"});
W("ordklass",{sv:"ordklass",m:rx("ordklass(en|er|erna)?"),d:t3("En grupp ord som fungerar på samma sätt, till exempel substantiv eller verb.","A group of words that work in the same way, for example nouns or verbs.","مجموعة كلمات تعمل بالطريقة نفسها، مثل الأسماء أو الأفعال."),ex:"substantiv, verb, adjektiv",tr:{en:"word class",ar:"نوع الكلمة"}});
W("substantiv",{sv:"substantiv",m:rx("substantiv(et|en)?"),d:t3("Ett ord för en sak, en person, ett djur eller en plats.","A word for a thing, a person, an animal or a place.","كلمة تدلّ على شيء أو شخص أو حيوان أو مكان."),ex:"en domare, ett mål, Sara",tr:{en:"noun",ar:"اسم"}});
W("adjektiv",{sv:"adjektiv",m:rx("adjektiv(et|en)?"),d:t3("Ett ord som beskriver hur något eller någon är.","A word that describes what something or someone is like.","كلمة تصف كيف يكون شيء أو شخص."),ex:"stolt, besviken, röd",tr:{en:"adjective",ar:"صفة"}});
