/* ---------------- unit 4: Skollaget i tidningen (substantiv: en/ett, bestämd form, plural) ---------------- */
W("reporter",{sv:"reporter (en)",m:rx("(reporter(n)?|reportrar(na)?)"),d:t3("En person som tar reda på nyheter och berättar om dem i tidningen, på radio eller på tv.","A person who finds out news and reports it in the newspaper, on radio or on TV.","شخص يبحث عن الأخبار وينقلها في الصحيفة أو الإذاعة أو التلفاز."),ex:"Reportern ställde frågor till laget.",tr:{en:"reporter",ar:"مراسل صحفي"},syn:["journalist"],wrong:["domare","rektor"],gap:["En","reporter","från tidningen skrev om matchen."],gapForm:"reporter",form:"en reporter – reportrar"});
W("intervju",{sv:"intervju (en), intervjua",m:rx("intervju(n|er|erna|a|ar|ade|at|ad)?"),d:t3("Ett samtal där någon ställer frågor och en annan svarar, ofta för en tidning.","A conversation where someone asks questions and another person answers, often for a newspaper.","حديث يطرح فيه شخص أسئلة ويجيب آخر، غالبًا من أجل صحيفة."),ex:"Amir gav en intervju till tidningen.",tr:{en:"interview",ar:"مقابلة"},syn:["samtal"],wrong:["tävling","läxa"],gap:["Tidningen gjorde en","intervju","med tränaren efter matchen."],gapForm:"intervju",form:"en intervju – intervjuer · intervjua – intervjuade"});
W("rubrik",{sv:"rubrik (en)",m:rx("rubrik(en|er|erna)?"),d:t3("Den korta texten med stora bokstäver över en artikel.","The short text in big letters above an article.","النص القصير بأحرف كبيرة فوق المقال."),ex:"Rubriken stod på första sidan.",tr:{en:"headline",ar:"عنوان"},syn:["överskrift"],wrong:["bild","sida"],gap:["Amir läste den stora","rubriken","på första sidan."],gapForm:"rubriken",form:"en rubrik – rubriker"});
W("invanare",{sv:"invånare (en)",m:rx("invånar(e|en|na)"),d:t3("En person som bor på en viss plats.","A person who lives in a certain place.","شخص يسكن في مكان معيّن."),ex:"Hagaby har 8 000 invånare.",tr:{en:"inhabitant, resident",ar:"ساكن"},syn:["boende"],opp:["besökare"],wrong:["turist","spelare"],gap:["Många","invånare","i Hagaby kom för att titta."],gapForm:"invånare",form:"en invånare – invånare"});
W("lokal",{sv:"lokal",m:rx("lokal(a|t)?"),d:t3("Som hör till en viss ort eller ett visst område, inte till hela landet.","Belonging to a certain town or area, not to the whole country.","يخصّ بلدة أو منطقة معيّنة، لا البلد كلّه."),ex:"Mamma läser den lokala tidningen.",tr:{en:"local",ar:"محلّي"},syn:["från orten"],opp:["nationell"],wrong:["rolig","snabb"],gap:["Laget var med i den","lokala","tidningen."],gapForm:"lokala",form:"lokal – lokalt – lokala"});
W("enligt",{sv:"enligt",m:rx("enligt"),d:t3("Som någon säger, eller som det står i något.","As someone says, or as it says in something.","حسب ما يقوله شخص ما، أو حسب ما هو مكتوب في شيء ما."),ex:"Enligt domaren var matchen spännande.",tr:{en:"according to",ar:"حسب"},syn:["som någon säger"],wrong:["bakom","utan"],gap:["Det var 300 personer på läktaren,","enligt","tidningen."],gapForm:"enligt",form:"enligt (preposition)"});
W("handelse",{sv:"händelse (en)",m:rx("händelse(n|r|rna)?"),d:t3("Något som händer, ofta något viktigt eller ovanligt.","Something that happens, often something important or unusual.","شيء يحدث، غالبًا يكون مهمًّا أو غير عادي."),ex:"Finalen var veckans stora händelse.",tr:{en:"event",ar:"حَدَث"},syn:["evenemang"],wrong:["fråga","plats"],gap:["Finalen var veckans stora","händelse","i Hagaby."],gapForm:"händelse",form:"en händelse – händelser"});
W("fira",{sv:"fira",m:rx("fira(r|de|t)?"),d:t3("Göra något roligt för att visa att man är glad över något.","Do something fun to show that you are happy about something.","أن تفعل شيئًا ممتعًا لتُظهر أنك سعيد بشيء ما."),ex:"Skolan firar segern med tårta.",tr:{en:"celebrate",ar:"يحتفل"},syn:["ha fest för"],opp:["sörja"],wrong:["städa","träna"],gap:["Hela skolan ska","fira","segern med tårta."],gapForm:"fira",form:"fira – firade – har firat"});
W("enord",{sv:"en-ord",m:rx("en-ord(en|et)?"),d:t3("Ett substantiv som har en framför sig.","A noun that has en in front of it.","اسم تسبقه كلمة en."),ex:"en rubrik, en match",tr:{en:"en-word (common gender)",ar:"اسم من نوع en"}});
W("ettord",{sv:"ett-ord",m:rx("ett-ord(en|et)?"),d:t3("Ett substantiv som har ett framför sig.","A noun that has ett in front of it.","اسم تسبقه كلمة ett."),ex:"ett lag, ett mål",tr:{en:"ett-word (neuter)",ar:"اسم من نوع ett"}});
W("bestamd",{sv:"bestämd form",m:rx("bestämd(a)? form(en)?"),d:t3("Formen för något vi redan vet vilket det är. På svenska blir det en ändelse.","The form for something we already know about. In Swedish it is an ending.","الصيغة لشيء نعرفه مسبقًا. في السويدية تكون نهاية تُضاف إلى الكلمة."),ex:"rubriken, laget",tr:{en:"definite form",ar:"صيغة المعرفة"}});
W("plural",{sv:"plural",m:rx("plural(en|form(en)?)?"),d:t3("Formen för flera av något.","The form for more than one of something.","صيغة الجمع لأكثر من شيء واحد."),ex:"rubriker, lag, flickor",tr:{en:"plural",ar:"الجمع"}});
