W("skylla",{sv:"skylla på",m:rx("skyll(a|er|de|t)( på)?"),d:t3("Säga att någon annan har gjort något dåligt.","Say that someone else did something bad.","أن تقول إن شخصًا آخر هو من فعل شيئًا سيئًا."),ex:"Elias skyllde på Amir.",tr:{en:"blame",ar:"يلوم"},syn:["anklaga"],wrong:["hjälpa","fråga"],gap:["Elias","skyllde","på Amir fast Amir var oskyldig."],gapForm:"skyllde",form:"skylla – skyllde – har skyllt"});
W("arlig",{sv:"ärlig",m:rx("ärlig(t|a)?"),d:t3("Som säger sanningen och inte lurar någon.","Who tells the truth and doesn't trick anyone.","من يقول الحقيقة ولا يخدع أحدًا."),ex:"Till slut var Elias ärlig.",tr:{en:"honest",ar:"صادق"},syn:["uppriktig"],opp:["oärlig"],wrong:["arg","snabb"],gap:["Det är bra att du är","ärlig","nu."],gapForm:"ärlig",form:"ärlig – ärligt – ärliga"});
